where a.is_delete = 0
and a.category_code = #{categoryCode}
and a.season_id = #{seasonId}
and a.tournament_id = #{tournamentId}
and a.announcement_status = #{announcementStatus}
and a.is_top = #{isTop}
and a.is_important = #{isImportant}

    and (a.title like concat('%', #{keyword}, '%')
         or a.summary like concat('%', #{keyword}, '%')
         or a.announcement_no like concat('%', #{keyword}, '%'))

order by a.is_top desc, a.is_important desc, a.publish_time desc, a.id desc

mapper.update:
update basket_announcement
set announcement_status = #{toStatus}, update_time = now()
where id = #{id} and is_delete = 0 and announcement_status = #{fromStatus}

update basket_announcement
set announcement_status = 1, publish_time = now(), offline_time = null, update_time = now()
where id = #{id} and is_delete = 0 and announcement_status = #{fromStatus}

update basket_announcement
set announcement_status = 2, offline_time = now(), is_top = 0, update_time = now()
where id = #{id} and is_delete = 0 and announcement_status = #{fromStatus}

update basket_announcement set is_delete = 1, update_time = now()
where id = #{id} and is_delete = 0 and announcement_status in
#{s}
